   829  FLAC__bool parse_md5(const char *src, FLAC__byte dest[16])
   830  {
   831          unsigned i, d;
   832          int c;
   833          FLAC__ASSERT(0 != src);
   834          if(strlen(src) != 32)
   835                  return false;
   836          /* strtoul() accepts negative numbers which we do not want, so we do it the hard way */
   837          for(i = 0; i < 16; i++) {
   838                  c = (int)(*src++);
   839                  if(isdigit(c))
   840                          d = (unsigned)(c - '0');
   841                  else if(c >= 'a' && c <= 'f')
   842                          d = (unsigned)(c - 'a') + 10u;
   843                  else if(c >= 'A' && c <= 'F')
   844                          d = (unsigned)(c - 'A') + 10u;
   845                  else
   846                          return false;
   847                  d <<= 4;
   848                  c = (int)(*src++);
   849                  if(isdigit(c))
   850                          d |= (unsigned)(c - '0');

